/* Chai-1 scientific result composition using bounded ndarray projections. */
/* SPDX-License-Identifier: GPL-3.0-only */

const STYLE = `.chai-result{display:grid;gap:1rem;padding:1rem}.chai-result h2,.chai-result h3,.chai-result p{margin:0}.chai-section{display:grid;gap:.55rem;min-width:0}.chai-candidates,.chai-actions{display:flex;flex-wrap:wrap;gap:.45rem}.chai-candidates button[aria-current="true"]{outline:2px solid var(--accent);outline-offset:2px}.chai-columns{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,26rem),1fr));gap:1rem}.chai-figure{position:relative;overflow:hidden}.chai-figure canvas{display:block;max-width:100%}.chai-figure .pair-matrix-label{position:absolute;color:var(--muted);font-size:11px}.chai-figure .af3-label-x{transform:translateX(-50%)}.chai-figure .af3-label-y{transform:translateY(-50%)}.chai-figure .af3-title{color:var(--ink);font-size:12px}.chai-figure .af3-title-y{transform:translate(-50%,-50%) rotate(-90deg);white-space:nowrap}`;
function list(v){return Array.isArray(v)?v:v?[v]:[]} function section(t,n){const e=document.createElement("section");e.className="chai-section";const h=document.createElement("h3");h.textContent=t;e.appendChild(h);if(n){const p=document.createElement("p");p.className="scientific-note";p.textContent=n;e.appendChild(p)}return e} function message(t){const p=document.createElement("p");p.className="preview-message";p.textContent=t;return p} async function json(url,signal){const r=window.REvoDesignAuth?await window.REvoDesignAuth.authFetch(url,{signal}):await fetch(url,{credentials:"same-origin",signal});if(!r.ok)throw new Error("Chai-1 evidence could not be loaded.");return r.json()} async function ndarray(a,signal){if(!a||!a.ndarray_url)return null;try{return await window.REvoComputeScientific.loadNumericProjection(a,{signal})}catch(error){if(signal&&signal.aborted)throw error;return null}} function reshape(v){if(!v||v.shape.length!==2||v.shape[0]!==v.shape[1]||v.values.length!==v.shape[0]*v.shape[1])return null;const rows=[];for(let i=0;i<v.values.length;i+=v.shape[1])rows.push(v.values.slice(i,i+v.shape[1]));return rows}
export default{async mount(host,context){const S=window.REvoComputeScientific;if(!S)throw new Error("Scientific result components are unavailable.");const structures=list(context.files.get("structures")),summaries=list(context.files.get("summaries")),locals=list(context.files.get("local_confidence")),paes=list(context.files.get("pae")),pdes=list(context.files.get("pde"));const aligned=[summaries,locals,paes,pdes].every(v=>v.length===structures.length);let local=null,paeMatrix=null,pdeMatrix=null;const root=document.createElement("div");root.className="chai-result";const style=document.createElement("style");style.textContent=STYLE;const h=document.createElement("h2");h.textContent="Chai-1 prediction";const intro=document.createElement("p");intro.textContent="Confidence-ranked structures with bounded local and pairwise confidence projections.";root.append(style,h,intro);const candidates=section("Ranked structures","Ranks are published by Chai-1 aggregate confidence.");const candidateHost=document.createElement("div");candidateHost.className="chai-candidates";const actions=document.createElement("div");actions.className="chai-actions";candidates.append(candidateHost,actions);root.appendChild(candidates);const columns=document.createElement("div");columns.className="chai-columns";const metrics=section("Prediction confidence","Published metrics for the selected rank. pLDDT and pTM are model confidence estimates, not experimental validation.");const metricHost=document.createElement("div");metrics.appendChild(metricHost);const confidence=section("Local confidence","Per-token pLDDT on Chai-1's persisted 0 to 1 scale.");const confidenceHost=document.createElement("div");confidence.appendChild(confidenceHost);columns.append(metrics,confidence);root.appendChild(columns);function matrixSection(title,note){const group=section(title,note),figure=document.createElement("div");figure.className="chai-figure";const canvas=document.createElement("canvas");canvas.tabIndex=0;canvas.setAttribute("role","grid");const readout=document.createElement("p");readout.className="matrix-readout";readout.setAttribute("role","status");figure.appendChild(canvas);group.append(figure,readout);root.appendChild(group);return{figure,canvas,readout}}const paeView=matrixSection("Predicted aligned error","PAE in angstroms; lower is better."),pdeView=matrixSection("Predicted distance error","PDE in angstroms; lower is better.");host.replaceChildren(root);paeMatrix=new S.PairMatrix({figure:paeView.figure,canvas:paeView.canvas,readout:paeView.readout,minimum:0,unit:"angstrom",xTitle:"Aligned token",yTitle:"Scored token",legendTitle:"PAE",decimals:1});pdeMatrix=new S.PairMatrix({figure:pdeView.figure,canvas:pdeView.canvas,readout:pdeView.readout,minimum:0,unit:"angstrom",xTitle:"Token",yTitle:"Token",legendTitle:"PDE",decimals:1});
    function clearCandidate(text){actions.replaceChildren();metricHost.replaceChildren(message(text));confidenceHost.replaceChildren();if(local){local.destroy();local=null}for(const view of[paeView,pdeView]){view.figure.hidden=true;view.readout.textContent=""}}
    function show(value,view,renderer){const projected=reshape(value);if(!projected){view.readout.textContent="This array exceeds the bounded interactive limit.";return}view.figure.hidden=false;const labels=projected.map((_,i)=>String(i+1));renderer.setData({values:projected,xLabels:labels,yLabels:labels})}
    async function select(structure,index,request){clearCandidate("Loading candidate evidence...");if(!aligned){clearCandidate("Candidate evidence counts do not align.");return}try{const [summary,plddt,pae,pde]=await Promise.all([json(summaries[index].url,request.signal),ndarray(locals[index],request.signal),ndarray(paes[index],request.signal),ndarray(pdes[index],request.signal)]);if(!request.current())return;const open=document.createElement("button");open.type="button";open.className="btn btn-soft";open.textContent="Open selected structure";open.addEventListener("click",()=>context.services.openFile(structure));actions.replaceChildren(open);new S.ScalarMetricGrid(metricHost,[{label:"Aggregate score",value:summary.aggregate_score,unit:"score",meaning:"Higher is better"},{label:"pTM",value:summary.ptm,unit:"score",meaning:"Higher is better"},{label:"ipTM",value:summary.iptm,unit:"score",meaning:"Higher is better"},{label:"Inter-chain clashes",value:summary.has_inter_chain_clashes?"Yes":"No"}]);if(plddt&&plddt.shape.length===1)local=new S.LocalConfidenceSeries(confidenceHost,{series:[{label:"pLDDT",values:plddt.values}],xLabel:"Token index",yLabel:"pLDDT",unit:"score",direction:"higher is better",yMin:0,yMax:1});else confidenceHost.replaceChildren(message("Local pLDDT exceeds the bounded interactive limit."));show(pae,paeView,paeMatrix);show(pde,pdeView,pdeMatrix);return true}catch(error){if(error.name!=="AbortError"&&request.current())clearCandidate(error.message||"Chai-1 evidence could not be loaded.")}}const selector=new S.CandidateSelector(candidateHost,{items:structures,store:context.selection,label:(_,i)=>"Rank "+i,onSelect:select});if(structures.length)await selector.select(0);else candidateHost.replaceChildren(message("No ranked structure was published."));return{destroy(){selector.destroy();if(local)local.destroy();paeMatrix.destroy();pdeMatrix.destroy()}}}};
